19	package org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.conf;
20	
21	import org.apache.hadoop.thirdparty.com.google.common.annotations.VisibleForTesting;
22	import org.apache.hadoop.yarn.server.resourcemanager.DBManager;
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	import org.apache.hadoop.conf.Configuration;
26	import org.apache.hadoop.fs.FileSystem;
27	import org.apache.hadoop.fs.Path;
28	import org.apache.hadoop.fs.permission.FsPermission;
29	import org.apache.hadoop.yarn.conf.YarnConfiguration;
30	import org.apache.hadoop.yarn.server.records.Version;
31	import org.apache.hadoop.yarn.server.resourcemanager.RMContext;
32	import org.iq80.leveldb.DB;
33	import org.iq80.leveldb.DBComparator;
34	import org.iq80.leveldb.DBException;
35	import org.iq80.leveldb.DBIterator;
36	import org.iq80.leveldb.Options;
37	import org.iq80.leveldb.WriteBatch;
38	
39	import java.io.ByteArrayInputStream;
40	import java.io.ByteArrayOutputStream;
41	import java.io.File;
42	import java.io.IOException;
43	import java.io.ObjectInput;
44	import java.io.ObjectInputStream;
45	import java.io.ObjectOutput;
46	import java.io.ObjectOutputStream;
47	import java.nio.charset.StandardCharsets;
48	import java.util.LinkedList;
49	import java.util.List;
50	import java.util.Map;
51	
52	import static org.fusesource.leveldbjni.JniDBFactory.bytes;
53	
54	/**
55	 * A LevelDB implementation of {@link YarnConfigurationStore}.
56	 */
57	public class LeveldbConfigurationStore extends YarnConfigurationStore {
58	
59	  public static final Logger LOG =
60	      LoggerFactory.getLogger(LeveldbConfigurationStore.class);
61	
62	  private static final String DB_NAME = "yarn-conf-store";
63	  private static final String LOG_KEY = "log";
64	  private static final String VERSION_KEY = "version";
65	  private static final String CONF_VERSION_NAME = "conf-version-store";
66	  private static final String CONF_VERSION_KEY = "conf-version";
67	  private DB db;
68	  private DBManager dbManager;
69	  private DBManager versionDbManager;
70	  private DB versionDb;
71	  private long maxLogs;
72	  private Configuration conf;
73	  private Configuration initSchedConf;
74	  @VisibleForTesting
75	  protected static final Version CURRENT_VERSION_INFO = Version
76	      .newInstance(0, 1);
77	
78	  @Override
79	  public void initialize(Configuration config, Configuration schedConf,
80	      RMContext rmContext) throws IOException {
81	    this.conf = config;
82	    this.initSchedConf = schedConf;
83	    this.dbManager = new DBManager();
84	    this.versionDbManager = new DBManager();
85	    try {
86	      initDatabase();
87	      this.maxLogs = config.getLong(
88	          YarnConfiguration.RM_SCHEDCONF_MAX_LOGS,
89	          YarnConfiguration.DEFAULT_RM_SCHEDCONF_LEVELDB_MAX_LOGS);
90	      long compactionIntervalMsec = config.getLong(
91	          YarnConfiguration.RM_SCHEDCONF_LEVELDB_COMPACTION_INTERVAL_SECS,
92	          YarnConfiguration
93	              .DEFAULT_RM_SCHEDCONF_LEVELDB_COMPACTION_INTERVAL_SECS) * 1000;
94	      dbManager.startCompactionTimer(compactionIntervalMsec,
95	          this.getClass().getSimpleName());
96	    } catch (Exception e) {
97	      throw new IOException(e);
98	    }
99	  }
100	
101	  @Override
102	  public void format() throws Exception {
103	    close();
104	    FileSystem fs = FileSystem.getLocal(conf);
105	    fs.delete(getStorageDir(DB_NAME), true);
106	  }
107	
108	  private void initDatabase() throws Exception {
109	    Path confVersion = createStorageDir(CONF_VERSION_NAME);
110	    Options confOptions = new Options();
111	    confOptions.createIfMissing(false);
112	    File confVersionFile = new File(confVersion.toString());
113	
114	    versionDb = versionDbManager.initDatabase(confVersionFile, confOptions,
115	        this::initVersionDb);
116	
117	    Path storeRoot = createStorageDir(DB_NAME);
118	    Options options = new Options();
119	    options.createIfMissing(false);
120	    options.comparator(new DBComparator() {
121	      @Override
122	      public int compare(byte[] key1, byte[] key2) {
123	        String key1Str = new String(key1, StandardCharsets.UTF_8);
124	        String key2Str = new String(key2, StandardCharsets.UTF_8);
125	        if (key1Str.equals(key2Str)) {
126	          return 0;
127	        } else if (key1Str.equals(VERSION_KEY)) {
128	          return 1;
129	        } else if (key2Str.equals(VERSION_KEY)) {
130	          return -1;
131	        } else if (key1Str.equals(LOG_KEY)) {
132	          return 1;
133	        } else if (key2Str.equals(LOG_KEY)) {
134	          return -1;
135	        }
136	        return key1Str.compareTo(key2Str);
137	      }
138	
139	      @Override
140	      public String name() {
141	        return "keyComparator";
142	      }
143	
144	      public byte[] findShortestSeparator(byte[] start, byte[] limit) {
145	        return start;
146	      }
147	
148	      public byte[] findShortSuccessor(byte[] key) {
149	        return key;
150	      }
151	    });
152	    LOG.info("Using conf database at {}", storeRoot);
153	    File dbFile = new File(storeRoot.toString());
154	    db = dbManager.initDatabase(dbFile, options, this::initDb);
155	  }
156	
157	  private void initVersionDb(DB database) {
158	    database.put(bytes(CONF_VERSION_KEY), bytes(String.valueOf(0)));
159	  }
160	
161	  private void initDb(DB database) {
162	    WriteBatch initBatch = database.createWriteBatch();
163	    for (Map.Entry<String, String> kv : initSchedConf) {
164	      initBatch.put(bytes(kv.getKey()), bytes(kv.getValue()));
165	    }
166	    database.write(initBatch);
167	    increaseConfigVersion();
168	  }
169	
170	  private Path createStorageDir(String storageName) throws IOException {
171	    Path root = getStorageDir(storageName);
172	    FileSystem fs = FileSystem.getLocal(conf);
173	    fs.mkdirs(root, new FsPermission((short) 0700));
174	    return root;
175	  }
176	
177	  private Path getStorageDir(String storageName) throws IOException {
178	    String storePath = conf.get(YarnConfiguration.RM_SCHEDCONF_STORE_PATH);
179	    if (storePath == null) {
180	      throw new IOException("No store location directory configured in " +
181	          YarnConfiguration.RM_SCHEDCONF_STORE_PATH);
182	    }
183	    return new Path(storePath, storageName);
184	  }
185	
186	  @Override
187	  public void close() throws IOException {
188	    dbManager.close();
189	    versionDbManager.close();
190	  }
191	
192	  @Override
193	  public void logMutation(LogMutation logMutation) throws IOException {
194	    if (maxLogs > 0) {
195	      LinkedList<LogMutation> logs = deserLogMutations(db.get(bytes(LOG_KEY)));
196	      logs.add(logMutation);
197	      if (logs.size() > maxLogs) {
198	        logs.removeFirst();
199	      }
200	      db.put(bytes(LOG_KEY), serLogMutations(logs));
201	    }
202	  }
203	
204	  @Override
205	  public void confirmMutation(LogMutation pendingMutation,
206	      boolean isValid) {
207	    WriteBatch updateBatch = db.createWriteBatch();
208	    if (isValid) {
209	      for (Map.Entry<String, String> changes :
210	          pendingMutation.getUpdates().entrySet()) {
211	        if (changes.getValue() == null || changes.getValue().isEmpty()) {
212	          updateBatch.delete(bytes(changes.getKey()));
213	        } else {
214	          updateBatch.put(bytes(changes.getKey()), bytes(changes.getValue()));
215	        }
216	      }
217	      increaseConfigVersion();
218	    }
219	    db.write(updateBatch);
220	  }
221	
222	  private byte[] serLogMutations(LinkedList<LogMutation> mutations) throws
223	      IOException {
224	    ByteArrayOutputStream baos = new ByteArrayOutputStream();
225	    try (ObjectOutput oos = new ObjectOutputStream(baos)) {
226	      oos.writeObject(mutations);
227	      oos.flush();
228	      return baos.toByteArray();
229	    }
230	  }
231	
232	  // Because of type erasure casting to LinkedList<LogMutation> will be
233	  // unchecked. A way around that would be to iterate over the logMutations
234	  // which is overkill in this case.
235	  @SuppressWarnings("unchecked")
236	  private LinkedList<LogMutation> deserLogMutations(byte[] mutations) throws
237	      IOException {
238	    if (mutations == null) {
239	      return new LinkedList<>();
240	    }
241	
242	    try (ObjectInput input = new ObjectInputStream(
243	        new ByteArrayInputStream(mutations))) {
244	      return (LinkedList<LogMutation>) input.readObject();
245	    } catch (ClassNotFoundException e) {
246	      throw new IOException(e);
247	    }
248	  }
249	
250	  @Override
251	  public synchronized Configuration retrieve() {
252	    DBIterator itr = db.iterator();
253	    itr.seekToFirst();
254	    Configuration config = new Configuration(false);
255	    while (itr.hasNext()) {
256	      Map.Entry<byte[], byte[]> entry = itr.next();
257	      String key = new String(entry.getKey(), StandardCharsets.UTF_8);
258	      String value = new String(entry.getValue(), StandardCharsets.UTF_8);
259	      if (key.equals(LOG_KEY) || key.equals(VERSION_KEY)) {
260	        break;
261	      }
262	      config.set(key, value);
263	    }
264	    return config;
265	  }
266	
267	  private void increaseConfigVersion() {
268	    long configVersion = getConfigVersion() + 1L;
269	    versionDb.put(bytes(CONF_VERSION_KEY),
270	        bytes(String.valueOf(configVersion)));
271	  }
272	
273	  @Override
274	  public long getConfigVersion() {
275	    String version = new String(versionDb.get(bytes(CONF_VERSION_KEY)),
276	        StandardCharsets.UTF_8);
277	    return Long.parseLong(version);
278	  }
279	
280	  @Override
281	  public List<LogMutation> getConfirmedConfHistory(long fromId) {
282	    return null; // unimplemented
283	  }
284	
285	  @Override
286	  public Version getConfStoreVersion() throws Exception {
287	    return dbManager.loadVersion(VERSION_KEY);
288	  }
289	
290	  @VisibleForTesting
291	  @Override
292	  protected LinkedList<LogMutation> getLogs() throws Exception {
293	    return deserLogMutations(db.get(bytes(LOG_KEY)));
294	  }
295	
296	  @VisibleForTesting
297	  protected DB getDB() {
298	    return db;
299	  }
300	
301	  @Override
302	  public void storeVersion() throws Exception {
303	    try {
304	      storeVersion(CURRENT_VERSION_INFO);
305	    } catch (DBException e) {
306	      throw new IOException(e);
307	    }
308	  }
309	
310	  @VisibleForTesting
311	  protected void storeVersion(Version version) {
312	    dbManager.storeVersion(VERSION_KEY, version);
313	  }
314	
315	  @Override
316	  public Version getCurrentVersion() {
317	    return CURRENT_VERSION_INFO;
318	  }
319	}
